/**
 * Report Serializer - Converts Report to serializable DTO.
 *
 * PROBLEM:
 * The Report interface contains non-serializable data (Fiber references, ComponentType functions)
 * which makes it unsuitable for JSON.stringify(), IPC, or network transmission.
 *
 * SOLUTION:
 * Strip non-serializable fields (fiber, type). Keep only what's needed:
 * - sourceId already contains component name (e.g., "MyComponent#1@5")
 * - Metrics and numerical data
 * - No need to convert anything - just omit problematic fields
 *
 * USAGE:
 * ```typescript
 * const report = detector.report(50);
 * const dto = serializeReport(report);
 *
 * // Now safe to serialize
 * const json = JSON.stringify(dto);
 *
 * // Send over IPC/network
 * postMessage({ type: 'report', data: dto });
 * ```
 *
 * DESIGN:
 * - Minimal DTO - only what you need for metrics/analysis
 * - sourceId already has component name - no conversion needed
 * - Drop fiber and type fields completely
 *
 * The serializer is also the trust boundary between page-side React objects
 * and helper/offline consumers. A DTO must remain stable after the page is
 * gone, so it carries evidence and summaries rather than live object identity.
 */

import type { RenderedEvidenceStatus } from './rendered-evidence-store';
import type { AvalancheHookResult } from './avalanche-hooks';
import type { CommitMetricsDelta, IntegrationMode } from './commit-metrics-adapter';
import type { InputEventDetails } from './input-details';
import type { NetworkCaptureStatus, NetworkRequest } from './network-capture';
import type { PerfCaptureStatus, PerfEntry } from './perf-capture';
import type { ConsoleCaptureStatus, ConsoleEntry } from './console-capture';
import type { ScreenChange } from './screen-changes';
import type { DomCommitDiff } from './dom-diff';
import type { SuspenseLocation } from './suspense-location';
import type { ComponentRename } from './rendered-names';
import { toWireValue } from './wire-value';

/** A network request as it travels in a report: already plain data. */
export type NetworkRequestDTO = NetworkRequest;

// ============================================================================
// DTO TYPES (Serializable - no function refs, no Fiber refs)
// ============================================================================

/**
 * Commit stats tuple: [collateral, sources, restarts, performedWork, effects, memos, callbacks,
 * contextUpdates, unmountedComponents, unmountedSubtrees]. Mirrors CommitStats in reporter.tsx.
 */
export type CommitStatsDTO = [
  collateral: number,
  sources: number,
  restarts: number,
  performedWork: number,
  effects: number,
  memos: number,
  callbacks: number,
  contextUpdates: number,
  unmountedComponents: number,
  unmountedSubtrees: number,
];

/**
 * Per-commit counter deltas from the commit metrics adapter, keyed by counter
 * name. The counters depend on the adapter (see `meta.metricsAdapter`).
 */
export type CommitMetricsDeltaDTO = CommitMetricsDelta;


/**
 * Commit timing data - measures React commit duration and detector overhead.
 */
export interface CommitTimingDTO {
  /** performance.now() at commit hook start, on the `meta.timeOrigin` clock. */
  startTime: number;
  /** performance.now() when detector processing for this commit finished. */
  endTime: number;
  timeSinceLastCommit: number;
  detectorOverhead: number;
  /** Render slices since the previous commit; null when the build has no slice signal. */
  ticks: number | null;
  /** performance.now() when the commit reached the screen (end of the next frame's rendering update). */
  paintAt?: number;
  /** Slice timing behind `ticks` (`performance.now()` clock), or null. */
  render: {
    ticks: number;
    renderStart: number;
    renderEnd: number;
    workMs: number;
    yieldedMs: number;
    longestSliceMs: number;
    slices: Array<[number, number]>;
    slicesTruncated: boolean;
    partial: boolean;
  } | null;
}

/**
 * Report metadata - profiling context and overhead metrics.
 */
export interface ReportMetaDTO {
  version: number;
  /** `performance.timeOrigin` of the page (Unix epoch ms); the clock for every absolute timestamp. */
  timeOrigin: number;
  commits: number;
  config: {
    detectionLevel: 'stats' | 'sources' | 'amplifierMetrics' | 'amplifiers' | 'full';
    effectThrashMode: 'non-primitive' | 'all';
    captureFibers: boolean;
    historySize: number;
  };
  memoizedUpdatersSupport: {
    available: boolean;
    commitsWithData: number;
    coverage: string;
  };
  /** Commit-hook integration model. */
  integrationMode?: IntegrationMode;
  /** Id of the commit metrics adapter that drove the report, or null. */
  metricsAdapter?: string | null;
  /** Per-field availability for commitStats indices and metricsByCommit. */
  dataAvailability?: Record<string, boolean>;
  /** Render-tick signal: `sources` in use, or `reason` when unavailable. */
  renderTicks?: { available: boolean; sources: string[]; reason: string | null };
  /** Resource Timing capture behind `networkRequests`. Absent before report v8. */
  network?: NetworkCaptureStatus;
  /** Browser performance entry capture behind `perfEntries`. Absent before report v9. */
  perf?: PerfCaptureStatus;
  /** Console capture behind `consoleEntries`. Absent before report v10. */
  console?: ConsoleCaptureStatus;
  /** `renderedByCommit` budget and what it dropped. Absent before the budget existed. */
  renderedEvidence?: RenderedEvidenceStatus;
  /** `domByCommit` budget and what it dropped. Absent when DOM diff capture is off. */
  domDiff?: RenderedEvidenceStatus;
  /**
   * Authored names recovered from source maps for components that ran under a
   * minified name. Report text already uses `name`; `minifiedName` is the
   * runtime name. Absent when no name was recovered.
   */
  componentNames?: ComponentRename[];
  amplifiersMetrics?: {
    totalHookThrashes: number;
    affectedComponentCount: number;
  };
  timing: {
    totalDetectorOverhead: number;
    avgDetectorOverhead: number;
    totalTimeSpan: number;
    avgTimeBetweenCommits: number;
  };
}

/**
 * Minimal serializable source - just the metrics, no functions/fibers.
 * sourceId already contains component name (e.g., "MyComponent#1@5")
 */
export interface SourceDTO {
  sourceId: string;
  depth: number;
  collateralUpdates: number;
  maxCollateralUpdates: number;
  maxPenetrationDepth: number;
  causedUpdates: number;
  restartWaste?: number;
  maxRestartWaste?: number;
}

/**
 * Source entry in sourcesByCommit - which sources fired in each commit.
 */
export interface SourceByCommitDTO {
  sourceId: string;
  depth: number;
  collateral: number;
  rank: number | null;
  sourceIndex: number | null;
  /** Changed hooks; values are bounded JSON-safe copies (see `toWireValue`). */
  trashers?: Array<{ index: number; prevValue: unknown; currentValue: unknown }>;
  isRepeat?: boolean;
}

type ChangedHookSample = { index: number; prevValue: unknown; currentValue: unknown };

/** Live hook values can be circular (DOM refs, fibers) or huge; keep bounded copies. */
function wireTrashers(hooks: ChangedHookSample[]): ChangedHookSample[] {
  return hooks.map((hook) => ({
    index: hook.index,
    prevValue: toWireValue(hook.prevValue),
    currentValue: toWireValue(hook.currentValue),
  }));
}

/**
 * Serializable Report - minimal data for metrics and analysis.
 * All non-serializable fields (fiber, type) are omitted.
 */
export interface SuspenseBoundaryEventDTO {
  depth: number;
  /** Stable id of the boundary within the capture. */
  boundary?: number;
  entered: boolean;
  left: boolean;
  /** Parents, owners, and identifying props around the boundary. */
  location?: SuspenseLocation;
}

export interface UnmountSampleDTO {
  name: string;
  key: string | null;
  depth: number | null;
  count: number;
  source?: { fileName?: string; lineNumber?: number; columnNumber?: number } | null;
}

export type PropChangeKindDTO = 'same' | 'ref-changed' | 'scalar-changed' | 'added' | 'removed';

/** One key of a `ref-changed` object or array prop whose value differs. */
export interface PropKeyChangeDTO {
  key: string;
  kind: 'scalar-changed' | 'ref-changed' | 'added' | 'removed';
  prev?: PropValueSummaryDTO;
  current?: PropValueSummaryDTO;
}

/** Shallow key diff of a `ref-changed` plain object or array prop. */
export interface PropKeyDiffDTO {
  /** Present, and true, when every key holds the same value: only the identity changed. */
  sameShallow?: true;
  /** The first keys that differ, in key order; empty when `sameShallow`. */
  changedKeys?: PropKeyChangeDTO[];
  /** How many keys differ in total. */
  changedKeyCount?: number;
  /** Present, and true, when `changedKeys` lists fewer keys than `changedKeyCount`. */
  changedKeysTruncated?: true;
  /** Set instead of the fields above when a value has too many keys to compare: its key count. */
  keysNotCompared?: number;
}

/**
 * A prop value as one bounded line, such as `21`, `"text"`,
 * `function onClick`, `array(3)[1, 2, 3]` or `object{id,title}`.
 * See `prop-summary.ts` for the full format.
 */
export type PropValueSummaryDTO = string;

/**
 * One changed prop. `removed` has only `prev`; `added` only `current`;
 * `scalar-changed` has both. `ref-changed` has `current`, plus `prev` only
 * when the previous value's summary differs (its shape changed). A
 * `ref-changed` plain object or array also carries its shallow key diff
 * (`sameShallow`, `changedKeys`, ...; see `prop-key-diff.ts`), except in
 * `stats` mode.
 */
export interface PropChangeEvidenceDTO extends PropKeyDiffDTO {
  name: string;
  kind: PropChangeKindDTO;
  prev?: PropValueSummaryDTO;
  current?: PropValueSummaryDTO;
}

/** Fields at their default value are left out: no `null` ids, no `false`, no empty list, no all-zero counts. */
export interface RenderedComponentEvidenceDTO {
  sourceId: string;
  name: string;
  depth: number;
  /** Absent when the parent fiber is not a component. */
  parentSourceId?: string;
  /** Absent when no component's update caused this render. */
  ownerSourceId?: string;
  /** Present, and true, only when this component's own state changed. */
  isSelfSource?: true;
  /** Absent when no prop changed. */
  propChanges?: PropChangeEvidenceDTO[];
  /** Absent when all three are zero. */
  trasherCounts?: { effects: number; callbacks: number; memos: number };
}

export interface CommitInteractionActionDTO {
  id: number;
  lastCommitId: number;
  deltaTime: number;
  /** performance.now() at event capture time, on the `meta.timeOrigin` clock. */
  timestamp: number;
  action: string;
  location: {
    dom: {
      tag: string | null;
      text: string;
      nearestTestId: string | null;
    };
    targetFiber: {
      name: string | null;
      key: string | null;
      source: { fileName?: string; lineNumber?: number; columnNumber?: number } | null;
      ownerStackKind: 'owners' | 'parents';
      ownerStack: Array<{
        name: string | null;
        key: string | null;
        props: string[];
        hookCount: number;
        hookCountTruncated: boolean;
        hookCountMax: number;
        source: { fileName?: string; lineNumber?: number; columnNumber?: number } | null;
      }>;
    } | null;
  };
  /** Whether the browser received the event as input, plus key name and modifiers (no typed text). */
  event?: InputEventDetails;
}

export interface ReportDTO {
  meta: ReportMetaDTO;
  sources: SourceDTO[];
  commitStats: Record<number, CommitStatsDTO>;
  suspenseByCommit: Record<number, SuspenseBoundaryEventDTO[]>;
  sourcesByCommit?: Record<number, SourceByCommitDTO[]>;
  interactionsByCommit?: Record<number, CommitInteractionActionDTO[]>;
  renderedByCommit?: Record<number, RenderedComponentEvidenceDTO[]>;
  metricsByCommit?: Record<number, CommitMetricsDeltaDTO>;
  commitTimings?: Record<number, CommitTimingDTO>;
  /** Requests that finished during the capture. Absent before report v8. */
  networkRequests?: NetworkRequestDTO[];
  /** Browser performance entries recorded during the capture. Absent before report v9. */
  perfEntries?: PerfEntry[];
  /** Console messages, uncaught errors, and unhandled rejections. Absent before report v10. */
  consoleEntries?: ConsoleEntry[];
  /** Screen area each commit changed. Absent when screen capture is off. */
  screenByCommit?: Record<number, ScreenChange>;
  /** DOM changes each commit made. Absent when DOM diff capture is off. */
  domByCommit?: Record<number, DomCommitDiff>;
  /** Plugin Avalanche hook results (packs), keyed by hook id. */
  hooks?: Record<string, AvalancheHookResult>;
}

// ============================================================================
// SERIALIZATION FUNCTION
// ============================================================================

/**
 * Convert Report to serializable DTO.
 *
 * Strips non-serializable fields (fiber, type) and keeps only essential metrics.
 *
 * @param report - Full Report from detector.report()
 * @returns Minimal serializable ReportDTO safe for JSON.stringify()
 */
export function serializeReport(report: {
  meta: ReportMetaDTO;
  sources: Array<{
    sourceId: string;
    depth: number;
    causedUpdates: number;
    collateralUpdates: number;
    maxCollateralUpdates: number;
    maxPenetrationDepth: number;
    restartWaste?: number;
    maxRestartWaste?: number;
  }>;
  commitStats: Record<number, CommitStatsDTO>;
  sourcesByCommit?: Record<
    number,
    Array<{
      sourceId: string;
      depth: number;
      collateral: number;
      rank: number | null;
      sourceIndex: number | null;
      hooks?: Array<{ index: number; prevValue: unknown; currentValue: unknown }>;
      trashers?: Array<{ index: number; prevValue: unknown; currentValue: unknown }>;
      isRepeat?: boolean;
    }>
  >;
  suspenseByCommit?: Record<number, Array<{ depth: number; boundary?: number; entered: boolean; left: boolean; location?: SuspenseLocation; fiber?: unknown }>>;
  interactionsByCommit?: Record<number, CommitInteractionActionDTO[]>;
  renderedByCommit?: Record<number, RenderedComponentEvidenceDTO[]>;
  metricsByCommit?: Record<number, CommitMetricsDeltaDTO>;
  commitTimings?: Record<number, CommitTimingDTO>;
  networkRequests?: NetworkRequestDTO[];
  perfEntries?: PerfEntry[];
  consoleEntries?: ConsoleEntry[];
  screenByCommit?: Record<number, ScreenChange>;
  domByCommit?: Record<number, DomCommitDiff>;
  hooks?: Record<string, AvalancheHookResult>;
}): ReportDTO {
  // Just extract the fields we need - no conversion necessary
  const sources: SourceDTO[] = report.sources.map((source) => ({
    sourceId: source.sourceId,
    depth: source.depth,
    causedUpdates: source.causedUpdates,
    collateralUpdates: source.collateralUpdates,
    maxCollateralUpdates: source.maxCollateralUpdates,
    maxPenetrationDepth: source.maxPenetrationDepth,
    ...(source.restartWaste !== undefined && { restartWaste: source.restartWaste }),
    ...(source.maxRestartWaste !== undefined && { maxRestartWaste: source.maxRestartWaste }),
  }));

  // Serialize sourcesByCommit (strip non-serializable type/fiber fields)
  const sourcesByCommit: Record<number, SourceByCommitDTO[]> | undefined = report.sourcesByCommit
    ? Object.fromEntries(
        Object.entries(report.sourcesByCommit).map(([commitId, commitSources]) => [
          commitId,
          commitSources.map((src) => ({
            sourceId: src.sourceId,
            depth: src.depth,
            collateral: src.collateral,
            rank: src.rank,
            sourceIndex: src.sourceIndex,
            ...((src.trashers || src.hooks) && { trashers: wireTrashers((src.trashers || src.hooks)!) }),
            ...(src.isRepeat && { isRepeat: true }),
          })),
        ])
      )
    : undefined;

  // Serialize suspenseByCommit — strip fiber refs (not serializable), keep scalar event fields
  const suspenseByCommit: Record<number, SuspenseBoundaryEventDTO[]> = {};
  if (report.suspenseByCommit) {
    for (const [k, evts] of Object.entries(report.suspenseByCommit)) {
      suspenseByCommit[Number(k)] = evts.map((e) => ({
        depth: e.depth,
        ...(typeof e.boundary === 'number' && { boundary: e.boundary }),
        entered: e.entered,
        left: e.left,
        ...(e.location && { location: e.location }),
      }));
    }
  }

  return {
    meta: report.meta,
    sources,
    commitStats: report.commitStats,
    suspenseByCommit,
    ...(sourcesByCommit && { sourcesByCommit }),
    ...(report.interactionsByCommit && { interactionsByCommit: report.interactionsByCommit }),
    ...(report.renderedByCommit && { renderedByCommit: report.renderedByCommit }),
    ...(report.metricsByCommit && { metricsByCommit: report.metricsByCommit }),
    ...(report.commitTimings && { commitTimings: report.commitTimings }),
    ...(report.networkRequests && { networkRequests: report.networkRequests.map((request) => ({ ...request })) }),
    ...(report.perfEntries && { perfEntries: report.perfEntries.map((entry) => ({ ...entry })) }),
    ...(report.consoleEntries && { consoleEntries: report.consoleEntries.map((entry) => ({ ...entry })) }),
    ...(report.screenByCommit && { screenByCommit: report.screenByCommit }),
    ...(report.domByCommit && { domByCommit: report.domByCommit }),
    ...(report.hooks && { hooks: report.hooks }),
  };
}
