/**
 * Avalanche API command dispatchers.
 *
 * Faithful port of the original `evalAvalanche` / `readAvalancheStatus` /
 * `getReport` / `tupleToStats` block from chippy-page-bridge.js
 * (lines ~357–565). Action names, return shapes, and edge cases are
 * preserved exactly so the bridge can replace its inline body with a
 * one-line shim and the helper protocol over the WebSocket continues
 * to work unchanged.
 */

import { hookStepsAt } from '../avalanche/avalanche-hooks';
import { warmComponentTypes, type NameRecoveryStats } from './component-origin';
import { componentNamesIn, nameTokensIn } from './component-name-tokens';
import type { ComponentRename } from '../avalanche/rendered-names';
import { networkByCommit, networkView, type CommitNetwork } from '../avalanche/network-signals';
import { buildTimeline } from '../avalanche/timeline';
import { buildDomDiffView } from '../avalanche/dom-diff-view';
import { compactLatestAction, tupleToStats, UPSTREAM_COMMIT_STAT_KEYS } from '../avalanche/commit-stats';
import { buildSummaryView } from '../avalanche/summary-view';
import { perfForCommit, perfView } from '../avalanche/perf-signals';
import { consoleForCommit, consoleView } from '../avalanche/console-signals';

export { tupleToStats, UPSTREAM_COMMIT_STAT_KEYS };

// ─── Type definitions ────────────────────────────────────────────────────

export type AvalancheApiStatus = {
  installed: boolean;
  /** True when the capture is paused (panel Stop). Absent on bundles before pause. */
  paused?: boolean;
  /** performance.now() when the capture was paused, or null while it records. */
  pausedAt?: number | null;
  hasMetricsGlobal: boolean;
  commitCount: number;
  /** `'adapter:<id>'`, `'devtools'`, or `'none'`. */
  integrationMode: `adapter:${string}` | 'devtools' | 'none';
  /** Active commit metrics adapter id. Absent on bundles before the adapter seam. */
  metricsAdapter?: string | null;
  /** Network requests captured so far. Absent on bundles before network capture. */
  networkRequests?: number;
  /** Console entries captured so far. Absent on bundles before console capture. */
  consoleEntries?: number;
  /** `renderedByCommit` budget and what it dropped. Absent on bundles before the budget. */
  renderedEvidence?: { maxEntries: number; entries: number; commits: number; evicted: { commits: number; entries: number; throughCommit: number } | null } | null;
};

export type ReadStatusResult =
  | { ok: true; available: true; status: AvalancheApiStatus }
  | { ok: false; available: boolean; error: string; moduleKeys?: string[] | null; status?: undefined };

export type AvalancheCommand = {
  action?: string;
  /** How long the caller waits for the result; sizes whole-capture name recovery. */
  timeoutMs?: number;
  options?: Record<string, unknown>;
  count?: number;
  sourceId?: string;
  hookIndex?: number;
  window?: number;
  limit?: number;
  commitId?: number;
  include?: string[];
  maxItems?: number;
  top?: number;
  by?: string;
  /** `network`: case-insensitive regex over request URLs. `perf`: regex over entry names. `dom-diff`: regex over each change's op, node, components, markup, and props. */
  match?: string;
  /** `network`: initiator types to keep, such as fetch or xmlhttprequest. */
  initiators?: string[];
  /** `perf`: performance entry types to list, such as mark, measure, or long-animation-frame. */
  types?: string[] | string;
  /** `console`: levels to list, such as error,warn. */
  levels?: string[] | string;
  /** `console`: include messages Chippy itself wrote. */
  includeChippy?: boolean;
  /** `timeline`, `dom-diff`, `perf`: first and last commit ids of the window. */
  fromCommit?: number;
  toCommit?: number;
  /** `timeline`: requests shorter than this are left out. */
  minRequestMs?: number;
  /** `timeline`: case-insensitive regex of request URLs to leave out. */
  exclude?: string;
  /** `timeline`: `full` adds the structured lanes to the summary and renderings. */
  format?: string;
  [key: string]: unknown;
};

type Reportish = { toSerializable?: () => unknown } & Record<string, unknown>;

export type AvalancheApi = {
  status?: () => AvalancheApiStatus;
  install?: (options?: Record<string, unknown>) => unknown;
  uninstall?: () => unknown;
  reset?: () => unknown;
  exportLast?: (n?: number) => unknown;
  report?: (topN?: number) => Reportish;
  /** Component types the detector recorded; used to recover production names. */
  /** Component types behind the given report source ids. */
  componentTypesFor?: (sourceIds: Iterable<string>) => unknown[];
  /** Component types of rendered entries still recorded as `Anonymous`. */
  unnamedRenderedTypes?: () => unknown[];
  /** Component types the capture named with any of `names`, or every named type. */
  componentTypesNamed?: (names?: Iterable<string>) => unknown[];
  debugHook?: (sourceId: string, hookIndex: number, windowSize?: number) => unknown;
  [key: string]: unknown;
};

export type AvalancheModule = Record<string, unknown>;

export type EvalAvalancheResult = {
  ok: boolean;
  /** Production builds: names recovered for the components this result names. */
  nameRecovery?: NameRecoveryStats;
  /**
   * Production builds: authored names in this result that replaced a
   * minified runtime name, with that name. Absent when none apply.
   */
  componentNames?: ComponentRename[];
  available: boolean;
  action: string;
  status?: AvalancheApiStatus;
  result?: unknown;
  payload?: unknown;
  error?: string;
  count?: number;
  total?: number;
  rows?: unknown[];
  by?: string;
  validBy?: string[];
  validInclude?: string[];
  commitId?: number;
  found?: boolean;
};

// ─── Helpers ─────────────────────────────────────────────────────────────

function compactNetwork(network: CommitNetwork | undefined, maxItems: number) {
  const rows = (items: CommitNetwork['landedBefore']) => items.slice(0, maxItems);
  return {
    landedBefore: rows(network?.landedBefore ?? []),
    landedBeforeTotal: network?.landedBefore.length ?? 0,
    startedAfter: rows(network?.startedAfter ?? []),
    startedAfterTotal: network?.startedAfter.length ?? 0,
    startedDuringRender: rows(network?.startedDuringRender ?? []),
    startedDuringRenderTotal: network?.startedDuringRender.length ?? 0,
    inFlight: network?.inFlight ?? 0,
  };
}

type ReportSlice = { raw: Reportish; serial: Record<string, unknown> } | { error: string } | null;

/**
 * Every command reads the report with all sources. The detector's default
 * keeps only the top 10, which left commit-peek rows outside them `missing`
 * and capped hot-sources at 10 whatever the limit.
 */
export const REPORT_ALL_SOURCES = Number.POSITIVE_INFINITY;

export function getReport(api: AvalancheApi | null | undefined): ReportSlice {
  if (!api || typeof api.report !== 'function') return null;
  try {
    const r = api.report(REPORT_ALL_SOURCES);
    if (r && typeof (r as Reportish).toSerializable === 'function') {
      return { raw: r as Reportish, serial: (r as Reportish).toSerializable!() as Record<string, unknown> };
    }
    return { raw: r as Reportish, serial: r as Record<string, unknown> };
  } catch (e) {
    return { error: (e as { message?: string })?.message || String(e) };
  }
}

// ─── Status ──────────────────────────────────────────────────────────────

export function readAvalancheStatus(
  api: AvalancheApi | null | undefined,
  mod: AvalancheModule | null | undefined,
): ReadStatusResult {
  if (!api || typeof api.status !== 'function') {
    return {
      ok: false,
      available: !!mod,
      error: '__AVALANCHE__ API not available',
      moduleKeys: mod ? Object.keys(mod) : null,
    };
  }
  try {
    const status = api.status();
    return { ok: true, available: true, status };
  } catch (e) {
    return { ok: false, available: true, error: (e as { message?: string })?.message || String(e) };
  }
}

// ─── Dispatcher ──────────────────────────────────────────────────────────

export function evalAvalanche(
  command: AvalancheCommand | null | undefined,
  api: AvalancheApi | null | undefined,
  mod: AvalancheModule | null | undefined,
): EvalAvalancheResult {
  let slice: ReportSlice | undefined;
  const report = () => (slice === undefined ? (slice = getReport(api)) : slice);
  const result = runAvalanche(command, api, mod, report);
  return slice ? withComponentNames(result, slice) : result;
}

/** Lists the renames that apply to a result; exports carry them in `meta`. */
function withComponentNames(result: EvalAvalancheResult, slice: NonNullable<ReportSlice>): EvalAvalancheResult {
  if (!result.ok || 'error' in slice || WHOLE_CAPTURE_ACTIONS.has(result.action)) return result;
  const meta = (slice.serial as { meta?: { componentNames?: unknown } }).meta;
  const componentNames = componentNamesIn(result, meta?.componentNames);
  return componentNames.length > 0 ? { ...result, componentNames } : result;
}

function runAvalanche(
  command: AvalancheCommand | null | undefined,
  api: AvalancheApi | null | undefined,
  mod: AvalancheModule | null | undefined,
  report: () => ReportSlice,
): EvalAvalancheResult {
  const action = String(command?.action || 'status');
  if (!api) {
    return { ok: false, available: false, action, error: '__AVALANCHE__ not available' };
  }
  try {
    switch (action) {
      case 'install': {
        const opts = command && typeof command.options === 'object' ? command.options : undefined;
        const res = api.install?.(opts);
        return { ok: true, available: true, action, result: res, status: readAvalancheStatus(api, mod).status };
      }
      case 'uninstall':
        api.uninstall?.();
        return { ok: true, available: true, action, status: readAvalancheStatus(api, mod).status };
      case 'reset':
      case 'clear':
        api.reset?.();
        return { ok: true, available: true, action, status: readAvalancheStatus(api, mod).status };
      case 'status':
        return { ok: true, available: true, action, status: readAvalancheStatus(api, mod).status };
      case 'export': {
        const r = report();
        if (!r) return { ok: false, available: true, action, error: 'report() unavailable' };
        if ('error' in r) return { ok: false, available: true, action, error: r.error };
        return { ok: true, available: true, action, payload: r.serial };
      }
      case 'export-last': {
        const count = Number(command?.count);
        const n = Number.isFinite(count) && count > 0 ? Math.floor(count) : 1;
        let res: unknown;
        try {
          res = api.exportLast?.(n);
        } catch (e) {
          return { ok: false, available: true, action, error: (e as { message?: string })?.message || String(e) };
        }
        if (res && typeof (res as Reportish).toSerializable === 'function') {
          res = (res as Reportish).toSerializable!();
        }
        return { ok: true, available: true, action, count: n, payload: res };
      }
      case 'debug-hook': {
        const sourceId = String(command?.sourceId || '');
        const hookIndex = Number(command?.hookIndex);
        const windowSize = Number(command?.window);
        if (!sourceId || !Number.isFinite(hookIndex)) {
          return { ok: false, available: true, action, error: 'debug-hook requires sourceId and numeric hookIndex' };
        }
        if (typeof api.debugHook !== 'function') {
          return { ok: false, available: true, action, error: 'debugHook() unavailable on __AVALANCHE__ API' };
        }
        const payload = api.debugHook(
          sourceId,
          Math.floor(hookIndex),
          Number.isFinite(windowSize) ? Math.max(0, Math.floor(windowSize)) : undefined,
        );
        return { ok: true, available: true, action, payload };
      }
      case 'hot-sources': {
        const limit = Number(command?.limit);
        const n = Number.isFinite(limit) && limit > 0 ? Math.floor(limit) : 20;
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        const sources = Array.isArray((r.serial as { sources?: unknown[] }).sources)
          ? ((r.serial as { sources: unknown[] }).sources as Array<Record<string, unknown>>)
          : [];
        const items = sources
          .slice()
          .sort((a, b) => Number(b?.collateralUpdates || 0) - Number(a?.collateralUpdates || 0))
          .slice(0, n)
          .map((s) => ({
            sourceId: s?.sourceId ?? null,
            depth: Number(s?.depth || 0),
            causedUpdates: Number(s?.causedUpdates || 0),
            collateralUpdates: Number(s?.collateralUpdates || 0),
            maxCollateralUpdates: Number(s?.maxCollateralUpdates || 0),
            maxPenetrationDepth: Number(s?.maxPenetrationDepth || 0),
            restartWaste: Number(s?.restartWaste || 0),
          }));
        return { ok: true, available: true, action, total: sources.length, payload: { count: items.length, items } };
      }
      case 'commit-peek': {
        const commitId = Number(command?.commitId);
        if (!Number.isFinite(commitId)) {
          return { ok: false, available: true, action, error: 'commit-peek requires numeric commitId' };
        }
        const include = Array.isArray(command?.include) && command!.include!.length
          ? command!.include!
          : ['stats', 'sources', 'timing', 'metrics', 'hooks'];
        const allowedInclude = ['stats', 'sources', 'timing', 'metrics', 'hooks', 'unmounts', 'actions', 'rendered', 'network', 'dom', 'perf', 'console'];
        const invalidInclude = include.filter((key) => !allowedInclude.includes(key));
        if (invalidInclude.length) {
          return {
            ok: false,
            available: true,
            action,
            error: 'unsupported commit-peek include value(s): ' + invalidInclude.join(','),
            validInclude: allowedInclude,
          };
        }
        const maxItems = Number.isFinite(Number(command?.maxItems))
          ? Math.max(1, Math.floor(Number(command!.maxItems)))
          : 50;
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        const ser = (r.serial || {}) as Record<string, Record<string, unknown>>;
        const tuple = ser.commitStats?.[commitId] || ser.commitStats?.[String(commitId)] || null;
        const sourceIds = (ser.sourcesByCommit?.[commitId] || ser.sourcesByCommit?.[String(commitId)] || []) as unknown[];
        const timing = ser.commitTimings?.[commitId] || ser.commitTimings?.[String(commitId)] || null;
        const metricsMap = ser.metricsByCommit;
        const metrics = metricsMap?.[commitId] || metricsMap?.[String(commitId)] || null;
        const actions = (ser.interactionsByCommit?.[commitId] || ser.interactionsByCommit?.[String(commitId)] || []) as unknown[];
        const rendered = (ser.renderedByCommit?.[commitId] || ser.renderedByCommit?.[String(commitId)] || []) as unknown[];
        const hookSteps = hookStepsAt(ser.hooks as Parameters<typeof hookStepsAt>[0], commitId);
        if (!tuple && !sourceIds.length && !timing && !metrics && !actions.length && !rendered.length && !Object.keys(hookSteps).length) {
          return { ok: true, available: true, action, commitId, found: false };
        }
        const sourcesById = new Map<unknown, Record<string, unknown>>();
        const allSources = (ser.sources as unknown as Array<Record<string, unknown>>) || [];
        for (const s of allSources) {
          if (s && s.sourceId != null) sourcesById.set(s.sourceId, s);
        }
        const out: Record<string, unknown> = { commitId, found: true };
        if (include.includes('stats')) out.stats = tupleToStats(tuple);
        if (include.includes('sources')) {
          const entries = Array.isArray(sourceIds) ? sourceIds : [];
          const slice = entries.slice(0, maxItems).map((entry) => {
            const e = entry as { sourceId?: unknown; collateral?: unknown; rank?: unknown; trashers?: unknown } | unknown;
            const sid = (typeof e === 'object' && e !== null && 'sourceId' in (e as object))
              ? (e as { sourceId: unknown }).sourceId
              : entry;
            const s = sourcesById.get(sid);
            return s
              ? {
                  sourceId: s.sourceId,
                  depth: s.depth,
                  collateralAtCommit: (typeof e === 'object' && e !== null && 'collateral' in (e as object)) ? (e as { collateral: unknown }).collateral : null,
                  rankAtCommit: (typeof e === 'object' && e !== null && 'rank' in (e as object)) ? (e as { rank: unknown }).rank : null,
                  trashers: (typeof e === 'object' && e !== null && 'trashers' in (e as object)) ? (e as { trashers: unknown }).trashers : undefined,
                  causedUpdatesTotal: s.causedUpdates,
                  collateralUpdatesTotal: s.collateralUpdates,
                }
              : { sourceId: sid, missing: true };
          });
          out.sources = slice;
          out.sourcesTotal = entries.length;
        }
        if (include.includes('timing')) out.timing = timing;
        if (include.includes('metrics')) out.metrics = metrics;
        // Pack extension results for this commit, keyed like report.hooks; absent without packs.
        if (include.includes('hooks') && ser.hooks) out.hooks = hookSteps;
        if (include.includes('actions')) {
          out.actions = actions.slice(0, maxItems);
          out.actionsTotal = actions.length;
        }
        if (include.includes('rendered')) {
          out.rendered = rendered.slice(0, maxItems);
          out.renderedTotal = rendered.length;
          // The capture's entry budget dropped the oldest commits' rendered evidence.
          const evicted = (ser.meta as { renderedEvidence?: { evicted?: { throughCommit?: number } | null } } | undefined)
            ?.renderedEvidence?.evicted;
          if (!rendered.length && evicted && Number(evicted.throughCommit) >= commitId) out.renderedEvicted = true;
        }
        if (include.includes('dom')) {
          // One change set: the commit's DOM changes have no order among themselves.
          const dom = (ser.domByCommit?.[commitId] || ser.domByCommit?.[String(commitId)] || null) as
            | { changes: unknown[]; truncated?: true }
            | null;
          out.dom = dom ? dom.changes.slice(0, maxItems) : [];
          out.domTotal = dom ? dom.changes.length : 0;
          if (dom?.truncated) out.domTruncated = true;
        }
        if (include.includes('network')) {
          out.network = compactNetwork(networkByCommit(ser, command?.window).get(commitId), maxItems);
        }
        if (include.includes('perf')) {
          const perf = perfForCommit(ser as Parameters<typeof perfForCommit>[0], commitId, maxItems);
          out.perf = perf.items;
          out.perfTotal = perf.total;
        }
        if (include.includes('console')) {
          const logged = consoleForCommit(ser as Parameters<typeof consoleForCommit>[0], commitId, maxItems);
          out.console = logged.items;
          out.consoleTotal = logged.total;
        }
        if (include.includes('unmounts')) {
          // Live identity samples live on the raw report (not in DTO/export).
          const raw = (r.raw || {}) as { unmountsByCommit?: Record<number | string, unknown> };
          const samples = (raw.unmountsByCommit?.[commitId] || raw.unmountsByCommit?.[String(commitId)] || null) as
            | Array<{ name: string; key: string | null; depth: number | null; count: number; source?: { fileName?: string; lineNumber?: number; columnNumber?: number } | null }>
            | null;
          out.unmounts = samples ? samples.slice(0, maxItems) : [];
          out.unmountsTotal = Array.isArray(samples) ? samples.length : 0;
        }
        return { ok: true, available: true, action, payload: out };
      }
      case 'describe-action': {
        const actionId = Number(command?.actionId);
        if (!Number.isFinite(actionId)) {
          return { ok: false, available: true, action, error: 'describe-action requires numeric actionId' };
        }
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        const ser = (r.serial || {}) as Record<string, Record<string, unknown>>;
        const byCommit = ser.interactionsByCommit || {};
        for (const [commitId, items] of Object.entries(byCommit)) {
          const actions = Array.isArray(items) ? items : [];
          const found = actions.find((item: any) => Number(item?.id) === actionId);
          if (found) {
            return {
              ok: true,
              available: true,
              action,
              payload: { actionId, commitId: Number(commitId), found: true, action: found },
            };
          }
        }
        return { ok: true, available: true, action, payload: { actionId, found: false } };
      }
      case 'commit-list': {
        const top = Number.isFinite(Number(command?.top)) ? Math.max(1, Math.floor(Number(command!.top))) : 20;
        const by = String(command?.by || 'collateral');
        const allowedKeys: string[] = (UPSTREAM_COMMIT_STAT_KEYS as readonly string[]).concat(['sources', 'ticks', 'network']);
        if (!allowedKeys.includes(by)) {
          return {
            ok: false,
            available: true,
            action,
            error: 'unsupported commit-list sort key: ' + by,
            validBy: allowedKeys,
          };
        }
        const sortKey = by;
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        const ser = (r.serial || {}) as Record<string, Record<string, unknown>>;
        const stats = ser.commitStats || {};
        const sourcesByCommit = ser.sourcesByCommit || {};
        const ids = Object.keys(stats);
        const network = networkByCommit(ser, command?.window);
        const rows = ids.map((id) => {
          const tuple = stats[id];
          const stat = tupleToStats(tuple);
          const srcs = sourcesByCommit[id] as unknown;
          const sourceCount = Array.isArray(srcs)
            ? srcs.length
            : srcs && typeof srcs === 'object'
              ? Object.keys(srcs).length
              : 0;
          const actions = (ser.interactionsByCommit?.[id] || []) as unknown[];
          const timing = ser.commitTimings?.[id] as { ticks?: unknown } | undefined;
          // null when the build exposes no render-slice signal (meta.renderTicks).
          const ticks = typeof timing?.ticks === 'number' ? timing.ticks : null;
          const net = network.get(Number(id));
          return {
            commitId: Number(id),
            stat,
            sourceCount,
            ticks,
            network: {
              landedBefore: net?.landedBefore.length ?? 0,
              startedAfter: net?.startedAfter.length ?? 0,
              startedDuringRender: net?.startedDuringRender.length ?? 0,
            },
            latestAction: actions.length ? compactLatestAction(actions[actions.length - 1]) : null,
          };
        });
        const sortValue = (row: typeof rows[number]): number => {
          if (sortKey === 'sources') return row.sourceCount || 0;
          if (sortKey === 'ticks') return row.ticks ?? -1;
          if (sortKey === 'network') return row.network.landedBefore;
          return row.stat?.[sortKey] || 0;
        };
        rows.sort((a, b) => sortValue(b) - sortValue(a));
        return { ok: true, available: true, action, by: sortKey, total: rows.length, rows: rows.slice(0, top) };
      }
      case 'network': {
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        const view = networkView(r.serial, {
          top: command?.top,
          by: command?.by,
          match: command?.match,
          initiators: command?.initiators,
          window: command?.window,
        });
        if ('error' in view) return { ok: false, available: true, action, error: view.error, ...(view.validBy && { validBy: [...view.validBy] }) };
        return { ok: true, available: true, action, payload: view.payload };
      }
      case 'perf': {
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        const view = perfView(r.serial as Parameters<typeof perfView>[0], {
          types: command?.types,
          top: command?.top,
          match: command?.match,
          fromCommit: command?.fromCommit,
          toCommit: command?.toCommit,
        });
        if ('error' in view) return { ok: false, available: true, action, error: view.error };
        return { ok: true, available: true, action, payload: view.payload };
      }
      case 'console': {
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        const view = consoleView(r.serial as Parameters<typeof consoleView>[0], {
          levels: command?.levels,
          top: command?.top,
          match: command?.match,
          fromCommit: command?.fromCommit,
          toCommit: command?.toCommit,
          chippy: command?.includeChippy,
        });
        if ('error' in view) return { ok: false, available: true, action, error: view.error };
        return { ok: true, available: true, action, payload: view.payload };
      }
      case 'timeline': {
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        const timeline = buildTimeline(r.serial as Parameters<typeof buildTimeline>[0], {
          fromCommit: command?.fromCommit,
          toCommit: command?.toCommit,
          minRequestMs: command?.minRequestMs,
          maxRequests: command?.top,
          exclude: command?.exclude,
          settleMap: command?.format === 'full' || command?.format === 'map',
        });
        if ('error' in timeline) return { ok: false, available: true, action, error: timeline.error };
        const { ok: _ok, lanes, ...rest } = timeline;
        return { ok: true, available: true, action, payload: command?.format === 'full' ? { ...rest, lanes } : rest };
      }
      case 'dom-diff': {
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        const view = buildDomDiffView(r.serial as Parameters<typeof buildDomDiffView>[0], {
          fromCommit: command?.fromCommit,
          toCommit: command?.toCommit,
          match: command?.match,
          top: command?.top,
          maxItems: command?.maxItems,
        });
        if ('error' in view) return { ok: false, available: true, action, error: view.error };
        return { ok: true, available: true, action, payload: view };
      }
      case 'summary': {
        const r = report();
        if (!r || 'error' in r) {
          return { ok: false, available: true, action, error: (r && 'error' in r ? r.error : 'report() unavailable') };
        }
        return { ok: true, available: true, action, payload: buildSummaryView(r.serial, { top: command?.top, maxItems: command?.maxItems }) };
      }
      // Removed: start, stop, metrics, help — not present on the current public surface.
      default:
        return { ok: false, available: true, action, error: 'Unknown avalanche action: ' + action };
    }
  } catch (error) {
    return { ok: false, available: true, action, error: (error as { message?: string })?.message || String(error) };
  }
}

// ─── Production names ────────────────────────────────────────────────────

/** Default time budget for recovering production names before a report. */
export const AVALANCHE_NAME_BUDGET_MS = 3000;
/** Upper bound for a whole-capture export, which can name hundreds of types. */
export const AVALANCHE_EXPORT_NAME_BUDGET_MS = 20000;

/**
 * Name recovery budget for one command. An export names every rendered type,
 * and the first resolves also load the bundles' source maps, so 3s often covers
 * only a few dozen types. An export may spend up to half of the caller's
 * timeout, leaving the rest for the report itself.
 */
export function nameBudgetFor(command: AvalancheCommand | null | undefined): number {
  const action = String(command?.action || 'status');
  const timeoutMs = Number(command?.timeoutMs);
  if (!WHOLE_CAPTURE_ACTIONS.has(action) || !Number.isFinite(timeoutMs)) return AVALANCHE_NAME_BUDGET_MS;
  return Math.min(AVALANCHE_EXPORT_NAME_BUDGET_MS, Math.max(AVALANCHE_NAME_BUDGET_MS, timeoutMs / 2));
}

/** Actions whose results name no components, or that change state. */
const NAME_FREE_ACTIONS = new Set(['install', 'uninstall', 'reset', 'clear', 'status', 'debug-hook', 'network']);
const SOURCE_ID = /^[^\s#@]+#\d+@-?\d+$/;
/** Actions that return every rendered entry, more ids than `sourceIdsIn` collects. */
const WHOLE_CAPTURE_ACTIONS = new Set(['export', 'export-last']);
const MAX_SOURCE_IDS = 2000;

/** Report source ids (`Name#instance@depth`) that appear anywhere in `value`. */
export function sourceIdsIn(value: unknown, limit = MAX_SOURCE_IDS): string[] {
  const found = new Set<string>();
  const seen = new Set<object>();
  const visit = (node: unknown, depth: number): void => {
    if (found.size >= limit) return;
    if (typeof node === 'string') {
      if (SOURCE_ID.test(node)) found.add(node);
      return;
    }
    if (!node || typeof node !== 'object' || depth > 10 || seen.has(node)) return;
    seen.add(node);
    if (Array.isArray(node)) {
      for (const item of node) visit(item, depth + 1);
      return;
    }
    for (const [key, item] of Object.entries(node)) {
      if (SOURCE_ID.test(key)) found.add(key);
      visit(item, depth + 1);
    }
  };
  visit(value, 0);
  return Array.from(found);
}

/**
 * Production builds: run the command, recover authored names for only the
 * components it mentions (by source id or by name), and run it again when
 * that changed a name, so ids read `ProjectList#1@3` instead of `cp#1@3` and
 * names in rendered entries, DOM anchors, and summaries read `Item`, not
 * `Qr`. Development pages and state-changing actions run once.
 */
export async function evalAvalancheWithNames(
  command: AvalancheCommand | null | undefined,
  api: AvalancheApi | null | undefined,
  mod: AvalancheModule | null | undefined,
  budgetMs = nameBudgetFor(command),
): Promise<EvalAvalancheResult> {
  const first = evalAvalanche(command, api, mod);
  const action = String(command?.action || 'status');
  if (!first.ok || NAME_FREE_ACTIONS.has(action) || typeof api?.componentTypesFor !== 'function') return first;
  const ids = sourceIdsIn(first);
  const wholeCapture = WHOLE_CAPTURE_ACTIONS.has(action);
  const named = typeof api.componentTypesNamed === 'function' ? api.componentTypesNamed.bind(api) : null;
  let types: unknown[];
  try {
    types = ids.length > 0 ? api.componentTypesFor(ids) : [];
    if (wholeCapture && typeof api.unnamedRenderedTypes === 'function') types = types.concat(api.unnamedRenderedTypes());
    // Names written as text (rendered entries, DOM anchors, labels) carry no source id.
    if (named) types = types.concat(wholeCapture ? named() : named(nameTokensIn(first)));
  } catch {
    return first;
  }
  if (types.length === 0) return first;
  const stats = await warmComponentTypes(types, budgetMs);
  if (!stats) return first;
  const again = stats.named > 0 ? evalAvalanche(command, api, mod) : first;
  return { ...again, nameRecovery: stats };
}
